// Resuelve el estado de la conversación combinando dos fuentes:
// - la data table (sobrevive a que se pierda el storage del browser)
// - lo que la extensión leyó del DOM de la conversación abierta
const payload = $('Normalizar Payload').first().json;
const guardado = $input.first().json || {};
const tieneFila = Boolean(guardado.idConversacion);

const mensaje = payload.mensaje || '';

// Detector avanzado de teléfonos: decodifica números escritos en palabras y tolera símbolos de ofuscación
function extraerTelefonoAvanzado(texto) {
  if (!texto) return '';
  let t = String(texto).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');

  const DECENAS = [
    { p: /\bnoventa\s+y\s+/gi, d: '9 ' },
    { p: /\bochenta\s+y\s+/gi, d: '8 ' },
    { p: /\bsetenta\s+y\s+/gi, d: '7 ' },
    { p: /\bsesenta\s+y\s+/gi, d: '6 ' },
    { p: /\bcincuenta\s+y\s+/gi, d: '5 ' },
    { p: /\bcuarenta\s+y\s+/gi, d: '4 ' },
    { p: /\btreinta\s+y\s+/gi, d: '3 ' },
    { p: /\bnoventa\b/gi, d: '90 ' },
    { p: /\bochenta\b/gi, d: '80 ' },
    { p: /\bsetenta\b/gi, d: '70 ' },
    { p: /\bsesenta\b/gi, d: '60 ' },
    { p: /\bcincuenta\b/gi, d: '50 ' },
    { p: /\bcuarenta\b/gi, d: '40 ' },
    { p: /\btreinta\b/gi, d: '30 ' },
    { p: /\bveintinueve\b/gi, d: '29 ' },
    { p: /\bveintiocho\b/gi, d: '28 ' },
    { p: /\bveintisiete\b/gi, d: '27 ' },
    { p: /\bveintiseis\b/gi, d: '26 ' },
    { p: /\bveinticinco\b/gi, d: '25 ' },
    { p: /\bveinticuatro\b/gi, d: '24 ' },
    { p: /\bveintitres\b/gi, d: '23 ' },
    { p: /\bveintidos\b/gi, d: '22 ' },
    { p: /\bveintiuno\b|\bveintiun\b/gi, d: '21 ' },
    { p: /\bveinte\b/gi, d: '20 ' },
    { p: /\bdiecinueve\b/gi, d: '19 ' },
    { p: /\bdieciocho\b/gi, d: '18 ' },
    { p: /\bdiecisiete\b/gi, d: '17 ' },
    { p: /\bdieciseis\b/gi, d: '16 ' },
    { p: /\bquince\b/gi, d: '15 ' },
    { p: /\bcatorce\b/gi, d: '14 ' },
    { p: /\btrece\b/gi, d: '13 ' },
    { p: /\bdoce\b/gi, d: '12 ' },
    { p: /\bonce\b/gi, d: '11 ' },
    { p: /\bdiez\b/gi, d: '10 ' },
    { p: /\bcero\b/gi, d: '0 ' },
    { p: /\buno\b|\bun\b|\buna\b/gi, d: '1 ' },
    { p: /\bdos\b/gi, d: '2 ' },
    { p: /\btres\b/gi, d: '3 ' },
    { p: /\bcuatro\b/gi, d: '4 ' },
    { p: /\bcinco\b/gi, d: '5 ' },
    { p: /\bseis\b/gi, d: '6 ' },
    { p: /\bsiete\b/gi, d: '7 ' },
    { p: /\bocho\b/gi, d: '8 ' },
    { p: /\bnueve\b/gi, d: '9 ' },
  ];

  for (const item of DECENAS) {
    t = t.replace(item.p, item.d);
  }

  const candidatos = t.match(/\+?\d[\d\s\-()./_*~|]{6,}\d/g) || [];
  const numeros = candidatos
    .map((c) => c.replace(/\D/g, ''))
    .filter((n) => n.length >= 8 && n.length <= 15);

  return numeros[0] || '';
}

const telDetectado = extraerTelefonoAvanzado(mensaje);
const numero = telDetectado || payload.numeroDelComprador || guardado.numero || '';
const numeroCompartido = Boolean(guardado.numeroCompartido) || Boolean(numero);
const esNumeroNuevo = !guardado.numeroCompartido && Boolean(numero);

const esPrimerMensaje = payload.yaEscribimos === null || payload.yaEscribimos === undefined
  ? !tieneFila
  : !payload.yaEscribimos;

const normalizado = mensaje.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');

const PATRONES_HUMANO = [
  /\b(sos|eres|es|son)\s+(un[ao]?\s+)?(bot|robot|maquina|ia)\b/,
  /\bbot\s*\?/,
  /habl\w*\s+con\s+(un[ao]?\s+)?(persona|humano|alguien)/,
  /(atiende|responde|contesta)\s+(un[ao]?\s+)?(persona|humano)/,
  /\bautomatic/,
  /\b(estafa|estafador|chorro|ladron)\b/,
  /\b(reclamo|garantia|devolucion|factura)\b/,
];
const pidioHumano = PATRONES_HUMANO.some((p) => p.test(normalizado));

function aFormatoWhatsApp(digitos) {
  if (!digitos) return '';
  let n = digitos;
  if (n.startsWith('54')) n = n.slice(2);
  if (n.startsWith('0')) n = n.slice(1);
  if (n.startsWith('9')) n = n.slice(1);
  n = n.replace(/^(\d{2,4})15(\d{6,8})$/, '$1$2');
  return `549${n}`;
}

