function detectarUbicacion(digitos) {
  if (!digitos) return 'Desconocida';
  let n = digitos.replace(/\D/g, '');
  if (n.startsWith('54')) n = n.slice(2);
  if (n.startsWith('0')) n = n.slice(1);
  if (n.startsWith('9')) n = n.slice(1);
  n = n.replace(/^(\d{2,4})15(\d{6,8})$/, '$1$2');

  for (const item of PREFIJOS) {
    if (n.startsWith(item.p)) return item.u;
  }
  return 'Argentina (Otra zona)';
}

