parameters.jsCode:
// Tres listas que la extensión necesita en cada barrido:
//
// - pendientes: les escribimos, pasó el tiempo de espera y todavía no se les
//   mandó el mensaje 2 (seguimiento). Se excluyen las que ya dejaron el
//   número (objetivo cumplido, volver a escribir solo molesta).
// - pendientesWeb: ya recibieron el mensaje 2, pasó otra espera y todavía no
//   se les mandó el mensaje 3 (la web). Mismo criterio de exclusión.
// - derivadas: quedaron en manos del humano. El ciclo no las toca más:
//   escribirle de nuevo a alguien que pidió hablar con una persona es peor
//   que no haber automatizado nada.
//
// El filtro se hace acá y no en la query para no depender de los operadores
// de fecha del nodo de data table.
const body = $('Webhook: Pendientes').first().json.body || {};
const minutos = Number(body.minutos ?? 30);
const minutosWeb = Number(body.minutosWeb ?? 60);
const limite = Date.now() - minutos * 60 * 1000;
const limiteWeb = Date.now() - minutosWeb * 60 * 1000;

const filas = $input.all()
  .map((item) => item.json)
  .filter((fila) => fila && fila.idConversacion);

const pendientes = filas
  .filter((fila) => !fila.numeroCompartido
    && !fila.derivadaAHumano
    && !fila.seguimientoEnviado
    && fila.ultimoEnvio
    && new Date(fila.ultimoEnvio).getTime() < limite)
  .map((fila) => fila.idConversacion);

const pendientesWeb = filas
  .filter((fila) => !fila.numeroCompartido
    && !fila.derivadaAHumano
    && fila.seguimientoEnviado
    && !fila.mensajeWebEnviado
    && fila.ultimoEnvio
    && new Date(fila.ultimoEnvio).getTime() < limiteWeb)
  .map((fila) => fila.idConversacion);

const derivadas = filas
  .filter((fila) => fila.derivadaAHumano)
  .map((fila) => fila.idConversacion);

return [{ json: { ok: true, pendientes, pendientesWeb, derivadas, total: filas.length } }];

// Detecta cuentas que dejaron de dar señales de vida.
//
// Por qué hace falta un latido propio y no alcanza con mirar ultimoEnvio de
// las conversaciones: ese campo solo se actualiza cuando el bot MANDA algo.
// Si no escribe ningún comprador, la tabla se ve igual de quieta con el bot
// vivo que con el bot muerto. El latido, en cambio, lo emite la extensión en
// cada barrido, escriba o no.
//
// Este chequeo corre en n8n y no en el browser a propósito: es el único
// control que sigue funcionando justo cuando el browser no está, que es el
// caso que queremos detectar.
//
// Se avisa UNA sola vez por caída (`avisado`), no en cada chequeo: una
// alerta que se repite cada hora es una alerta que se termina silenciando, y
// una cuenta retirada avisaría para siempre. El latido la desmarca cuando la
// cuenta vuelve, así que la próxima caída vuelve a avisar.
const HORAS_PARA_ALARMA = 2;
const ahora = Date.now();
const limite = ahora - HORAS_PARA_ALARMA * 60 * 60 * 1000;

const filas = $input.all()
  .map((item) => item.json)
  .filter((fila) => fila && fila.cuenta && fila.ultimoLatido);

const mudas = filas.filter((fila) => !fila.avisado
  && new Date(fila.ultimoLatido).getTime() < limite);

if (mudas.length === 0) return [];

const escaparHtml = (s) => String(s || '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const detalle = mudas
  .map((fila) => {
    const horas = Math.round((ahora - new Date(fila.ultimoLatido).getTime()) / 3600000);
    return `• <b>${escaparHtml(fila.cuenta)}</b> — ${horas} h sin actividad`;
  })
  .join('\n');

// Una fila por cuenta muda, para poder marcarlas todas como avisadas.
return mudas.map((fila) => ({
  json: {
    cuenta: fila.cuenta,
    ultimoLatido: fila.ultimoLatido,
    cantidad: mudas.length,
    horas: HORAS_PARA_ALARMA,
    detalle,
  },
}));

