const linkWhatsApp = linksWhatsApp[Math.floor(Math.random() * linksWhatsApp.length)];

return { json: { ...$input.first().json, estiloExtra, linkWhatsApp } };

// Safety net: permite solo los precios preestablecidos del catálogo
// (silla giratoria $75.000, silla fija $50.000, escritorio $115.000).
// Cualquier otro monto detectado se reemplaza por la respuesta segura.
const respuesta = $input.first().json.respuesta || '';
const linkWhatsApp = $input.first().json.linkWhatsApp || 'https://wa.me/c/5493625281890';

const PERMITIDOS = new Set([75000, 50000, 115000, 100000, 115, 100, 75, 50]);

function normalizar(mencion) {
  let t = String(mencion).toLowerCase().trim();
  let mult = 1;
  if (t.includes('mil')) { mult = 1000; t = t.replace(/mil/g, ''); }
  else if (t.endsWith('k')) { mult = 1000; t = t.slice(0, -1); }
  t = t.replace(/\$/g, '').replace(/\./g, '').replace(/,/g, '.').replace(/[^0-9.]/g, '');
  const n = parseFloat(t);
  return Number.isFinite(n) ? n * mult : null;
}

const PATRONES = [
  /\$\s*\d[\d.,]*(?:\s*(?:mil|k))?/gi,                      // $75.000, $50 mil
  /\b\d[\d.,]*(?:\s*(?:mil|k))?\s*(?:pesos?|usd|\$)/gi,     // 75 mil pesos, 50000$
  /\b(?:cuesta|vale|precio|sale|sale por|desde)\s+\d[\d.,]*(?:\s*(?:mil|k))?/gi, // cuesta 75 mil
  /\b\d{1,3}(?:\.\d{3})+\b/gi,                              // 75.000, 115.000, 1.500
  /\b\d{4,6}\b/gi,                                          // 75000, 50000, 115000
  /\b\d[\d.,]*(?:\s*(?:mil|k))\b/gi                         // 75 mil, 50k, 115 mil
];

const detectados = [];
for (const p of PATRONES) {
  const matches = respuesta.match(p) || [];
  for (const m of matches) {
    const valor = normalizar(m);
    if (valor !== null && !detectados.includes(valor)) detectados.push(valor);
