// Arma el texto del resumen del día. Los números los cuenta la extensión,
// que es la que sabe qué pasó en cada conversación; acá solo se formatea.
const cuerpo = $input.first().json.body || $input.first().json || {};

const n = (v) => Number(v || 0);
const contactados = n(cuerpo.contactados);
const respuestas = n(cuerpo.respuestas);
const numeros = n(cuerpo.numeros);
const seguimientos = n(cuerpo.seguimientos);
const derivadas = n(cuerpo.derivadas);

const escaparHtml = (s) => String(s ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

// La conversión es el número que importa: de cada 100 personas contactadas,
// cuántas dejaron el WhatsApp.
const conversion = contactados > 0
  ? `${Math.round((numeros / contactados) * 100)}%`
  : 'sin datos';

const sinResponder = Math.max(0, contactados - respuestas);

return [{
  json: {
    nombreCuenta: escaparHtml(cuerpo.nombreCuenta || 'sin identificar'),
    fecha: escaparHtml(cuerpo.fecha || ''),
    contactados,
    respuestas,
    numeros,
    seguimientos,
    derivadas,
    sinResponder,
    conversion,
  },
}];

