const saludo = (nombreComprador && nombreComprador !== 'el comprador') ? `Hola ${nombreComprador}!` : 'Hola, buenas!';

const pidioNumero = Math.random() < PROBABILIDAD_PEDIR_NUMERO;
let respuesta = '';

if (/escritorio|mesa|mdf|combo/i.test(producto)) {
