} else if (/gamer/i.test(producto)) {
  const piden = [
    `${saludo} Contamos con sillas gamer y ergonómicas con regulación de altura y respaldo alto desde $75.000 / $100.000.\nDejanos tu número y te mandamos las fotos y opciones por WhatsApp.`,
    `Buenas! Manejamos modelos ergonómicos y gamer con excelente soporte lumbar.\nPasame tu celu y te comparto los modelos disponibles con precios por WhatsApp.`
  ];
  const mandan = [
    `${saludo} Sí, tenemos sillas gamer y ergonómicas desde $75.000 con regulación de altura y respaldo ergonómico.\nMirá las fotos y modelos en el catálogo directo: ${linkWhatsApp}`,
    `Buenas! Te comparto el catálogo completo con todas las sillas gamer y de oficina: ${linkWhatsApp} — escribinos por ahí para ver colores y coordinar envío o retiro.`
  ];
  const lista = pidioNumero ? piden : mandan;
  respuesta = lista[Math.floor(Math.random() * lista.length)];
} else if (/fija|plastico|espera|apilable/i.test(producto)) {
  const piden = [
    `${saludo} Contamos con sillas fijas plásticas y tapizadas desde $50.000, ideales para oficinas y salas de espera.\nDejanos tu número de contacto y te pasamos el catálogo con fotos.`,
    `Buenas! Manejamos sillas fijas a partir de $50.000 por unidad y precios especiales por cantidad.\nPasame tu número y te mando las opciones por WhatsApp.`
  ];
  const mandan = [
    `${saludo} Sí, contamos con variedad de sillas fijas a partir de $50.000 (también precios por cantidad).\nAcá tenés acceso directo al catálogo: ${linkWhatsApp}`,
    `Buenas! Te paso el link para ver todos los modelos de sillas fijas y colores disponibles: ${linkWhatsApp} — cualquier consulta avisanos!`
  ];
  const lista = pidioNumero ? piden : mandan;
  respuesta = lista[Math.floor(Math.random() * lista.length)];
} else {
  // General / Sillas giratorias / Múltiples opciones
  const PIDEN_NUMERO = [
    'Hola, buenas. Te comento que contamos con sillas fijas desde $50.000, giratorias desde $75.000 y escritorios desde $100.000. También armamos combos.\nSi querés ver el catálogo completo, dejanos tu número y te lo enviamos por WhatsApp.',
    'Buenas! Manejamos sillas fijas desde $50.000, giratorias desde $75.000 y escritorios desde $100.000, más combos a medida.\nPasame tu número y te mando las fotos y modelos por WhatsApp.',
    'Hola! Tenemos sillas fijas a partir de $50.000, giratorias desde $75.000 y escritorios desde $100.000.\n¿Me dejás un número de contacto y te comparto el catálogo con fotos?',
    'Hola, cómo va. Las fijas arrancan en $50.000, giratorias en $75.000 y escritorios desde $100.000 (también combos).\nDejanos tu celu y te pasamos el catálogo directo al WhatsApp.',
    'Buenas tardes! Contamos con sillas de oficina fijas desde $50.000, giratorias desde $75.000 y escritorios desde $100.000.\nSi te interesa ver opciones y fotos, dejanos tu número y te escribimos.',
    'Hola! Cómo estás? Tenemos sillas fijas desde $50.000, giratorias a partir de $75.000 y escritorios desde $100.000.\nSi querés ver todos los modelos con fotos y medidas, pasanos tu WhatsApp y te mandamos el catálogo completo.',
    'Buenas! Qué tal? Manejamos fijas desde $50.000, giratorias desde $75.000 y escritorios desde $100.000, además de combos.\nDejanos un celu y te pasamos el catálogo directo con stock y precios actualizados.',
    'Hola, buenas! Contamos con variedad de opciones: fijas desde $50.000, giratorias desde $75.000 y escritorios a partir de $100.000.\nPasame tu número de contacto y te comparto el catálogo por WhatsApp así elegís tranquilo.',
    'Buenas! Te paso los valores de referencia: sillas fijas desde $50.000, ergonómicas giratorias desde $75.000 y escritorios desde $100.000.\n¿Nos dejás tu número para enviarte las fotos y promos vigentes por WhatsApp?'
  ];

  const MANDAN_CATALOGO = [
    `Hola, buenas! Contamos con sillas fijas desde $50.000, giratorias desde $75.000 y escritorios desde $100.000, más combos.\nAcá tenés el catálogo completo con fotos y precios: ${linkWhatsApp} — escribinos por ahí y coordinamos!`,
    `Buenas! Tenemos sillas fijas desde $50.000, giratorias desde $75.000 y escritorios a partir de $100.000.\nTe dejo el catálogo directo para ver todos los modelos: ${linkWhatsApp}`,
    `Hola! Sillas fijas desde $50.000, giratorias desde $75.000 y escritorios desde $100.000. También hacemos combos a medida.\nPodés mirar todo el catálogo acá: ${linkWhatsApp} y cualquier duda nos hablás por ahí.`,
    `Hola, cómo va. Los precios arrancan en $50.000 para fijas, $75.000 giratorias y $100.000 escritorios.\nEn este link tenés el catálogo completo con stock y fotos: ${linkWhatsApp}`,
    `Buenas! Te paso los valores base: fijas desde $50.000, giratorias desde $75.000 y escritorios desde $100.000.\nEntrando a ${linkWhatsApp} podés ver todos los artículos y consultarnos por WhatsApp.`,
    `Hola! Cómo estás? Te comento que tenemos sillas fijas desde $50.000, giratorias desde $75.000 y escritorios desde $100.000.\nPodés ver fotos, medidas y disponibilidad en el catálogo: ${linkWhatsApp} — cualquier consulta avisanos!`,
    `Buenas! Qué tal? Trabajamos fijas desde $50.000, giratorias desde $75.000 y escritorios a partir de $100.000.\nTe comparto el catálogo con todos los modelos: ${linkWhatsApp} — escribinos por ahí para coordinar entrega o retiro.`,
    `Hola, buenas! Manejamos sillas fijas desde $50.000, giratorias desde $75.000 y escritorios desde $100.000, más combos.\nAcá tenés acceso directo al catálogo completo con fotos: ${linkWhatsApp}`,
    `Buenas! Los precios base son: fijas $50.000, giratorias $75.000 y escritorios desde $100.000.\nMirá todos los modelos en stock acá: ${linkWhatsApp} y nos escribís por cualquier duda.`
  ];

  const variantes = pidioNumero ? PIDEN_NUMERO : MANDAN_CATALOGO;
  respuesta = variantes[Math.floor(Math.random() * variantes.length)];
}

return [{
  json: {
    respuesta,
    linkWhatsApp,
    pidioNumero,
    numeroRecibido: $('Detectar Número').first().json.hayNumero,
    necesitaHumano: false,
  },
}];

// Elige al azar una variación de registro para la respuesta y un enlace equivalente de WhatsApp.
// Rotar el link evita la firma de spam por URL estática idéntica repetida.
const variaciones = [
  'Hoy estás con apuro: respuestas todavía más cortas, casi telegráficas, y directo al catálogo sin vueltas.',
  'Hoy estás distendido: un toque más suelto y amable, podés arrancar con un "buenas!" o "hola, cómo va" sin pasarte de confianza.',
  'Hoy estás prolijo: respuestas más formales, sin abreviar, con la puntuación completa, pero seguís siendo vos.',
  'Hoy estás seco: sin saludos ni preguntas de cortesía, respuesta directa a lo que preguntan y el link al catálogo.',
  'Hoy estás conversador: además de responder, si la consulta da para eso, podés sumar una línea de charla antes del link.',
];

const linksWhatsApp = [
  'https://wa.me/c/5493625281890',
  'https://wa.me/5493625281890',
  'https://api.whatsapp.com/send?phone=5493625281890',
];

const estiloExtra = variaciones[Math.floor(Math.random() * variaciones.length)];
const linkWhatsApp = linksWhatsApp[Math.floor(Math.random() * linksWhatsApp.length)];

return { json: { ...$input.first().json, estiloExtra, linkWhatsApp } };

// Safety net: permite solo los precios preestablecidos del catálogo
// (silla giratoria $75.000, silla fija $50.000, escritorio $115.000).
// Cualquier otro monto detectado se reemplaza por la respuesta segura.
const respuesta = $input.first().json.respuesta || '';
const linkWhatsApp = $input.first().json.linkWhatsApp || 'https://wa.me/c/5493625281890';

const PERMITIDOS = new Set([75000, 50000, 115000, 100000, 115, 100, 75, 50]);

function normalizar(mencion) {
  let t = String(mencion).toLowerCase().trim();
  let mult = 1;
  if (t.includes('mil')) { mult = 1000; t = t.replace(/mil/g, ''); }
  else if (t.endsWith('k')) { mult = 1000; t = t.slice(0, -1); }
  t = t.replace(/\$/g, '').replace(/\./g, '').replace(/,/g, '.').replace(/[^0-9.]/g, '');
  const n = parseFloat(t);
  return Number.isFinite(n) ? n * mult : null;
}

const PATRONES = [
  /\$\s*\d[\d.,]*(?:\s*(?:mil|k))?/gi,                      // $75.000, $50 mil
  /\b\d[\d.,]*(?:\s*(?:mil|k))?\s*(?:pesos?|usd|\$)/gi,     // 75 mil pesos, 50000$
  /\b(?:cuesta|vale|precio|sale|sale por|desde)\s+\d[\d.,]*(?:\s*(?:mil|k))?/gi, // cuesta 75 mil
  /\b\d{1,3}(?:\.\d{3})+\b/gi,                              // 75.000, 115.000, 1.500
  /\b\d{4,6}\b/gi,                                          // 75000, 50000, 115000
  /\b\d[\d.,]*(?:\s*(?:mil|k))\b/gi                         // 75 mil, 50k, 115 mil
];

const detectados = [];
for (const p of PATRONES) {
  const matches = respuesta.match(p) || [];
  for (const m of matches) {
    const valor = normalizar(m);
    if (valor !== null && !detectados.includes(valor)) detectados.push(valor);
  }
}

const RESPUESTA_SEGURA = `Los precios los ves en el catálogo, ahí tenés todo con fotos: ${linkWhatsApp}`;

const hayNoPermitido = detectados.some(v => !PERMITIDOS.has(v));

if (hayNoPermitido) {
  console.log(`[Filtrar Precios] Precio no permitido: ${detectados.join(', ')}. Original: ${respuesta}`);
  return [{ json: { ...$input.first().json, respuesta: RESPUESTA_SEGURA } }];
}

return [$input.first()];

// Cuando el comprador deja su número, ya no le mandamos el catálogo ni
// volvemos a pedirle nada: confirmamos con naturalidad que lo agendamos
// y que nos contactamos en breve por WhatsApp.
const variantes = [
  '¡Buenísimo! A la brevedad te vamos a estar contactando por WhatsApp con toda la info.',
  'Dale impecable, ya te agendamos y en breve te mandamos mensajito por WhatsApp.',
  'De diez, en un ratito te escribimos por WhatsApp así te pasamos fotos y detalles.',
  'Genial, muchas gracias! Enseguida te estamos escribiendo por WhatsApp.',
  'Buenísimo, te hablamos al WhatsApp a la brevedad para coordinar.',
  'Dale perfecto, ahí te mandamos un WhatsApp en breve con todos los modelos disponibles.'
];

const respuesta = variantes[Math.floor(Math.random() * variantes.length)];

return [{
  json: {
    ...$input.first().json,
    respuesta,
    pidioNumero: false,
    numeroRecibido: true,
    necesitaHumano: false,
  }
}];

// Extrae y desduplica todas las conversaciones con número de teléfono de la tabla
const filas = $input.all().map(item => item.json);

function normalizarTelefono(num) {
  if (!num) return '';
  let n = String(num).replace(/\D/g, '');
  if (n.startsWith('54')) n = n.slice(2);
  if (n.startsWith('0')) n = n.slice(1);
  if (n.startsWith('9')) n = n.slice(1);
  n = n.replace(/^(\d{2,4})15(\d{6,8})$/, '$1$2');
  return n;
}

function extraerTelefonoAvanzado(texto) {
  if (!texto) return '';
  let t = String(texto).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');

  const DECENAS = [
    { p: /\bnoventa\s+y\s+/gi, d: '9 ' },
    { p: /\bochenta\s+y\s+/gi, d: '8 ' },
    { p: /\bsetenta\s+y\s+/gi, d: '7 ' },
    { p: /\bsesenta\s+y\s+/gi, d: '6 ' },
    { p: /\bcincuenta\s+y\s+/gi, d: '5 ' },
    { p: /\bcuarenta\s+y\s+/gi, d: '4 ' },
    { p: /\btreinta\s+y\s+/gi, d: '3 ' },
    { p: /\bnoventa\b/gi, d: '90 ' },
    { p: /\bochenta\b/gi, d: '80 ' },
    { p: /\bsetenta\b/gi, d: '70 ' },
    { p: /\bsesenta\b/gi, d: '60 ' },
    { p: /\bcincuenta\b/gi, d: '50 ' },
    { p: /\bcuarenta\b/gi, d: '40 ' },
    { p: /\btreinta\b/gi, d: '30 ' },
    { p: /\bveintinueve\b/gi, d: '29 ' },
    { p: /\bveintiocho\b/gi, d: '28 ' },
    { p: /\bveintisiete\b/gi, d: '27 ' },
    { p: /\bveintiseis\b/gi, d: '26 ' },
    { p: /\bveinticinco\b/gi, d: '25 ' },
    { p: /\bveinticuatro\b/gi, d: '24 ' },
    { p: /\bveintitres\b/gi, d: '23 ' },
    { p: /\bveintidos\b/gi, d: '22 ' },
    { p: /\bveintiuno\b|\bveintiun\b/gi, d: '21 ' },
    { p: /\bveinte\b/gi, d: '20 ' },
    { p: /\bdiecinueve\b/gi, d: '19 ' },
    { p: /\bdieciocho\b/gi, d: '18 ' },
    { p: /\bdiecisiete\b/gi, d: '17 ' },
    { p: /\bdieciseis\b/gi, d: '16 ' },
    { p: /\bquince\b/gi, d: '15 ' },
    { p: /\bcatorce\b/gi, d: '14 ' },
    { p: /\btrece\b/gi, d: '13 ' },
    { p: /\bdoce\b/gi, d: '12 ' },
    { p: /\bonce\b/gi, d: '11 ' },
    { p: /\bdiez\b/gi, d: '10 ' },
    { p: /\bcero\b/gi, d: '0 ' },
    { p: /\buno\b|\bun\b|\buna\b/gi, d: '1 ' },
    { p: /\bdos\b/gi, d: '2 ' },
    { p: /\btres\b/gi, d: '3 ' },
    { p: /\bcuatro\b/gi, d: '4 ' },
    { p: /\bcinco\b/gi, d: '5 ' },
    { p: /\bseis\b/gi, d: '6 ' },
    { p: /\bsiete\b/gi, d: '7 ' },
    { p: /\bocho\b/gi, d: '8 ' },
    { p: /\bnueve\b/gi, d: '9 ' },
  ];

  for (const item of DECENAS) {
    t = t.replace(item.p, item.d);
  }

  const candidatos = t.match(/\+?\d[\d\s\-()./_*~|]{6,}\d/g) || [];
  const numeros = candidatos
    .map((c) => c.replace(/\D/g, ''))
    .filter((n) => n.length >= 8 && n.length <= 15);

  return numeros[0] || '';
}

function extraerTelefono(fila) {
  if (!fila) return '';
  if (fila.numero && String(fila.numero).replace(/\D/g, '').length >= 6) {
    return String(fila.numero);
  }
  if (fila.numeroDelComprador && String(fila.numeroDelComprador).replace(/\D/g, '').length >= 6) {
    return String(fila.numeroDelComprador);
  }
  const txt = String(fila.mensaje || fila.ultimoMensaje || '');
  return extraerTelefonoAvanzado(txt);
}

const porNumero = new Map();

filas.forEach(f => {
  if (!f) return;
  const tel = extraerTelefono(f);
  const telNorm = normalizarTelefono(tel);
  if (!telNorm || telNorm.length < 6) return;

  const fechaActual = new Date(f.ultimoEnvio || f.fechaContacto || f.updatedAt || f.createdAt || 0).getTime();
  const previo = porNumero.get(telNorm);
  if (!previo || fechaActual > new Date(previo.ultimoEnvio || previo.fechaContacto || previo.updatedAt || previo.createdAt || 0).getTime()) {
    porNumero.set(telNorm, {
      ...f,
      numero: tel
    });
  }
});

const unicos = Array.from(porNumero.values()).sort((a, b) => new Date(b.ultimoEnvio || 0) - new Date(a.ultimoEnvio || 0));

const leads = unicos.map(l => ({
  cuenta: l.cuenta || 'marketplace',
  idConversacion: l.idConversacion,
  nombreComprador: l.nombreComprador && l.nombreComprador !== 'Comprador' ? l.nombreComprador : 'Comprador',
  numero: l.numero,
  ultimoEnvio: l.ultimoEnvio || new Date().toISOString(),
  derivadaAHumano: Boolean(l.derivadaAHumano),
  contactadoEnWhatsapp: Boolean(l.contactadoEnWhatsapp)
}));

return [{
  json: {
    ok: true,
    total: leads.length,
    leads,
    leadsNuevos: leads.filter(l => !l.contactadoEnWhatsapp && !l.derivadaAHumano),
    leadsSeguimiento: leads,
    todosUnicos: leads
  }
}];
